#nullable enable // autogenerated

using MVZ2.GameContent.Contraptions;
using MVZ2Logic.Grids;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Tools;
using UnityEngine;

namespace MVZ2.GameContent.Projectiles
{
    [AutoEntityBehaviourDefinition(VanillaProjectileNames.mineTNTSeed)]
    public class MineTNTSeed : EntityBehaviourDefinition
    {
        public MineTNTSeed(string nsp, string name) : base(nsp, name)
        {
        }
        public override void PostContactGround(Entity entity, Vector3 velocity)
        {
            base.PostContactGround(entity, velocity);
            var level = entity.Level;
            var column = entity.GetColumn();
            var lane = level.GetNearestEntityLane(entity.Position.z);
            var grid = level.GetGrid(column, lane);
            if (grid != null && grid.CanSpawnEntity(VanillaContraptionID.mineTNT))
            {
                var x = level.GetEntityColumnX(column);
                var z = level.GetEntityLaneZ(lane);
                var y = level.GetGroundY(x, z);
                level.Spawn(VanillaContraptionID.mineTNT, new Vector3(x, y, z), entity)?.Let(e =>
                {
                    MineTNT.GetRiseTimer(e)?.Let(timer => { timer.Frame = 31; });
                });
            }
            entity.Remove();
        }
    }
}
